def test_load_order_rows(monkeypatch):
    # Mock the cursor and its execute/ fetchall methods
    class DummyCursor:
        def execute(self, query):
            assert "SELECT id, status, total FROM orders" in query
        def fetchall(self):
            return [
                (1, "queued", 100.0),
                (2, "queued", 200.0),
            ]
    dummy_cursor = DummyCursor()
    result = load_order_rows("owner123", dummy_cursor)
    assert isinstance(result, list)
    assert len(result) == 2
    assert result[0] == {"id": 1, "status": "queued", "total": 100.0}
    assert result[1] == {"id": 2, "status": "queued", "total": 200.0}
